def _course_rows(anchor):
    """Return forty weekly courses spanning exactly twelve complete weeks."""
    first = anchor - timedelta(weeks=config.HISTORY_WEEKS)
    last = anchor + timedelta(weeks=config.FUTURE_WEEKS) - timedelta(days=1)
    rows = []
    for index, title in enumerate(config.DEMO_COURSES):
        weekday = index % 5 if index < config.DEMO_WEEKDAY_COURSES else 5 + index % 2
        start, end = config.DEMO_COURSE_TIMES[index % len(config.DEMO_COURSE_TIMES)]
        if title == 'Fitness Late':
            start, end = '21:00', '22:30'
        rows.append({'course_id': f'demo-sport-{index:02d}', 'sport': title, 'title': title,
                     'level': 'Intermediate' if 'Intermediate' in title else 'All levels',
                     'weekday': config.DEMO_WEEKDAY_NAMES[weekday],
                     'start_time': start, 'end_time': end,
                     'location': config.DEMO_SPORT_LOCATIONS[
                         index % len(config.DEMO_SPORT_LOCATIONS)],
                     'valid_from': first.isoformat(), 'valid_to': last.isoformat(),
                     'source_url': config.UNISPORT_URL, 'registration_url': config.UNISPORT_URL,
                     'description': 'Illustrative demo course, not a live timetable.',
                     'price_chf': '20.00' if title in ('Climbing', 'Bouldering') else '0'})
    return rows


def _demo_start(anchor, index, count, hour):
    """Spread dated fixtures over the configured history/future window."""
    days = (config.HISTORY_WEEKS + config.FUTURE_WEEKS) * config.DAYS_PER_WEEK
    day = anchor - timedelta(weeks=config.HISTORY_WEEKS) + timedelta(days=index * days // count)
    return datetime.combine(day, datetime.min.time()) + timedelta(hours=hour)


def _club_rows(anchor, rng):
    """Generate sixty club events with varied status, location and end availability."""
    rows = []
    for index in range(config.DEMO_CLUB_COUNT):
        name, category, title = config.DEMO_CLUBS[index % len(config.DEMO_CLUBS)]
        start = _demo_start(anchor, index, config.DEMO_CLUB_COUNT, 18 + index % 3)
        end = start + timedelta(minutes=config.DEFAULT_DURATION_MINUTES)
        event_type = 'Workshop' if 'workshop' in title else 'Talk'
        location = config.DEMO_CLUB_LOCATIONS[index % len(config.DEMO_CLUB_LOCATIONS)]
        if index in (17, 37, 57):
            event_type, location, end = 'Trip', 'Prague', start + timedelta(days=2)
        elif category == 'Social':
            event_type = 'Social'
        status = 'OPEN'
        if index in config.DEMO_FULL_INDICES:
            status = 'FULL'
        elif index in config.DEMO_CLOSED_INDICES:
            status = 'CLOSED'
        elif index % 11 == 0:
            status = 'APPLY'
        elif index % 13 == 0:
            status = 'Members Only'
        missing = index < config.DEMO_MISSING_END_COUNT and event_type != 'Trip'
        rows.append({'id': f'demo-club-{index:02d}', 'title': title,
                     'club': {'name': name, 'category': category}, 'start': start.isoformat(),
                     'end': None if missing else end.isoformat(), 'location': location,
                     'type': event_type, 'status': status, 'members_only': status == 'Members Only',
                     'description': 'Demo event; check the organizer for real offerings.',
                     'price': '0' if index % 2 == 0 else rng.choice(config.DEMO_PRICES[1:]),
                     'url': '', 'registration_url': ''})
    return rows


def _city_rows(anchor, rng):
    """Generate thirty dated city events with explicit end times."""
    rows = []
    for index in range(config.DEMO_CITY_COUNT):
        title, venue = config.DEMO_CITY_EVENTS[index % len(config.DEMO_CITY_EVENTS)]
        start = _demo_start(anchor, index, config.DEMO_CITY_COUNT, 19)
        rows.append({'id': f'demo-city-{index:02d}', 'title': title, 'organizer': venue,
                     'start': start.isoformat(), 'end': (start + timedelta(hours=2)).isoformat(),
                     'location': venue,
                     'description': 'Illustrative city event, not a live listing.',
                     'price': rng.choice(config.DEMO_PRICES), 'type': '', 'status': 'OPEN',
                     'url': '', 'registration_url': ''})
    return rows


def write_placeholder_sources(anchor_date, sources_dir=config.SOURCES_DIR, rng=None):
    """Write deterministic Excel and JSON source fixtures for one anchor week."""
    anchor = anchor_date - timedelta(days=anchor_date.weekday())
    sources_dir.mkdir(parents=True, exist_ok=True)
    # Course: U02 s5 – keep the random generator private and seeded.
    rng = rng or random.Random(config.RANDOM_SEED)
    paths = {}
    for source in config.SOURCES:
        paths[source] = sources_dir / config.PLACEHOLDER_NAMES[source]
    pd.DataFrame(_course_rows(anchor)).to_excel(paths['unisport'], index=False)
    for source, rows in (('uniclubs', _club_rows(anchor, rng)), ('city', _city_rows(anchor, rng))):
        payload = {'_meta': {'ai_citation': config.DEMO_CITATION, 'is_placeholder': True},
                   'events': rows}
        text = json.dumps(payload, ensure_ascii=False, indent=2)
        paths[source].write_text(text, encoding='utf-8')
    return paths


def _calendar_entry(uid, day, start_text, end_text, title, repeating=False, transparent=False):
    """Write one demo VEVENT in Zurich local time so weekly recurrences survive DST correctly."""
    start = datetime.combine(day, datetime.strptime(start_text, config.SOURCE_TIME_FORMAT).time())
    end = datetime.combine(day, datetime.strptime(end_text, config.SOURCE_TIME_FORMAT).time())
    lines = ['BEGIN:VEVENT', f'UID:demo-{uid}@weekwise',
             f'DTSTART;TZID={config.TIMEZONE_NAME}:{start:{config.ICS_LOCAL_FORMAT}}',
             f'DTEND;TZID={config.TIMEZONE_NAME}:{end:{config.ICS_LOCAL_FORMAT}}',
             f'SUMMARY:{calendar_export.escape_ics_text(title)}']
    if repeating:
        count = config.HISTORY_WEEKS + config.FUTURE_WEEKS
        lines.append(f'RRULE:FREQ=WEEKLY;COUNT={count}')
    if transparent:
        lines.append('TRANSP:TRANSPARENT')
    return lines + ['END:VEVENT']


def write_demo_calendar(anchor_date, path=config.DEMO_CALENDAR_FILE):
    """Write the reproducible HSG calendar from SPEC section 17.4 without an ICS writing library.

    :param anchor_date: date in the anchor week
    :param path: output path; tests supply an isolated temporary path
    :return: path of the generated UTF-8 calendar
    """
    anchor = anchor_date - timedelta(days=anchor_date.weekday())
    beginning = anchor - timedelta(weeks=config.HISTORY_WEEKS)
    lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', f'PRODID:{config.ICS_PRODID}', 'CALSCALE:GREGORIAN']
    for index, (weekday, start, end, title) in enumerate(config.DEMO_WEEKLY_CALENDAR):
        lines.extend(_calendar_entry(f'weekly-{index}', beginning + timedelta(days=weekday),
                                     start, end, title, repeating=True))
    for index, (offset, start, end, title, transparent) in enumerate(config.DEMO_CALENDAR_ONE_OFFS):
        lines.extend(_calendar_entry(f'oneoff-{index}', anchor + timedelta(days=offset),
                                     start, end, title, transparent=transparent))
    birthday = anchor + timedelta(days=config.DEMO_BIRTHDAY_WEEKDAY)
    lines.extend(['BEGIN:VEVENT', 'UID:demo-birthday@weekwise',
                  f'DTSTART;VALUE=DATE:{birthday:{config.ICS_DATE_FORMAT}}',
                  f'DTEND;VALUE=DATE:{birthday + timedelta(days=1):{config.ICS_DATE_FORMAT}}',
                  f'SUMMARY:{calendar_export.escape_ics_text(config.DEMO_BIRTHDAY_TITLE)}',
                  'END:VEVENT', 'END:VCALENDAR'])
    text = '\r\n'.join(calendar_export.fold_ics_line(line) for line in lines) + '\r\n'
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(text.encode('utf-8'))
    return path


def ensure_demo_calendar(connection, path=config.DEMO_CALENDAR_FILE, now=None):
    """Add the M2 calendar to an existing M1 database without resetting its source data."""
    if not path.exists():
        anchor = database.get_setting(connection, 'demo_anchor_date')
        day = date.fromisoformat(anchor) if anchor else config.local_now(now).date()
        write_demo_calendar(day, path)


def generate_all(connection, anchor_date=None, sources_dir=config.SOURCES_DIR,
                 snapshot_dir=config.SNAPSHOT_DIR, private_file=config.PRIVATE_SOURCES_FILE,
                 now=None):
    """Generate sources, calendar and M4 histories, preserving an existing local profile."""
    day = anchor_date if anchor_date is not None else config.local_now().date()
    anchor = day - timedelta(days=day.weekday())
    taxonomy = categories.load_taxonomy()
    categories.seed_categories(connection, taxonomy)
    rng = random.Random(config.RANDOM_SEED)
    write_placeholder_sources(anchor, sources_dir, rng)
    write_demo_calendar(anchor, sources_dir.parent / 'demo' / config.DEMO_CALENDAR_FILE.name)
    reports = importers.import_all(connection, taxonomy, include_past=True,
                                   sources_dir=sources_dir, snapshot_dir=snapshot_dir,
                                   private_file=private_file)
    if any(report['outcome'] != 'ok' for report in reports):
        raise ValueError('Demo setup could not import every source. Check your source files.')
    database.set_setting(connection, 'demo_anchor_date', anchor.isoformat())
    # A supplied anchor also fixes the default generation clock, independent of the host date.
    generation_now = now or datetime.combine(anchor, datetime.min.time())
    if anchor_date is None:
        generation_now = config.local_now(now)
    ensure_synthetic_data(connection, generation_now, rng)
    database.delete_past_unconfirmed_events(connection, generation_now)
    check_synthetic_data(connection, generation_now)
    database.set_setting(connection, 'setup_done', '1')
    return reports


def _affinities(profile, bundles, rng):
    """Keep hidden tastes only in memory; they never become model features or database fields."""
    result = {}
    for bundle in bundles:
        bounds = config.SYNTHETIC_AFFINITY_OTHER
        if bundle['direction_key'] in profile.directions:
            bounds = config.SYNTHETIC_AFFINITY_WANTED
        result[bundle['bundle_key']] = rng.uniform(*bounds)
    return result


def _synthetic_favorites(connection, user_id, tastes, bundles, targets, rng, now):
    """Choose the highest-affinity bundles and a few randomly selected clubs and series."""
    ordered = sorted(bundles, key=lambda bundle: tastes[bundle['bundle_key']], reverse=True)
    count = rng.randint(*config.SYNTHETIC_FAVORITE_BUNDLES)
    for bundle in ordered[:count]:
        database.add_favorite(connection, user_id, 'bundle', bundle['id'], now)
    for kind, ids in targets.items():
        count = min(len(ids), rng.randint(0, config.SYNTHETIC_FAVORITE_TARGETS_MAX))
        for target_id in rng.sample(ids, count):
            database.add_favorite(connection, user_id, kind, target_id, now)


def create_synthetic_users(connection, rng, now=None):
    """Create sixty seeded profiles and return their in-memory preferences and hidden tastes.

    :param connection: database with imported events and taxonomy
    :param rng: the generator shared by all generation steps
    :param now: fixed creation clock
    :return: dictionaries containing a profile and ephemeral bundle affinities
    """
    now = config.local_now(now)
    bundles = database.get_categories_df(connection).reset_index().to_dict('records')
    targets = database.get_favorite_target_ids(connection)
    users = []
    for index, name in enumerate(config.SYNTHETIC_NAMES[:config.N_SYNTHETIC_USERS]):
        code = config.SHOWCASE_CODES[index] if index < len(config.SHOWCASE_CODES) else None
        sharing = rng.random() < config.SYNTHETIC_SHARING_SHARE
        user_id = database.create_user(connection, name, True, sharing or code is not None,
                                        now, friend_code=code, rng=rng)
        count = rng.choices(config.SYNTHETIC_DIRECTION_COUNTS,
                            weights=config.SYNTHETIC_DIRECTION_WEIGHTS)[0]
        directions = rng.sample(list(config.DIRECTION_LABELS), count)
        database.set_user_directions(connection, user_id, directions)
        profile = database.get_user_profile(connection, user_id)
        tastes = _affinities(profile, bundles, rng)
        _synthetic_favorites(connection, user_id, tastes, bundles, targets, rng, now)
        users.append({'profile': database.get_user_profile(connection, user_id), 'tastes': tastes})
    return users


def create_synthetic_friendships(connection, rng, now=None):
    """Build symmetric friendships with degree three to six and a bounded random-fill phase."""
    ids = list(database.get_synthetic_users_df(connection).index)
    rng.shuffle(ids)
    links = {user_id: set() for user_id in ids}
    # A cycle plus opposite pairs gives every generated user three distinct friends.
    for index, user_id in enumerate(ids):
        for offset in (1, len(ids) // 2):
            friend_id = ids[(index + offset) % len(ids)]
            links[user_id].add(friend_id)
            links[friend_id].add(user_id)
    targets = {user_id: rng.randint(config.SYNTHETIC_FRIENDS_MIN,
                                    config.SYNTHETIC_FRIENDS_MAX) for user_id in ids}
    for attempt in range(config.SYNTHETIC_MAX_ATTEMPTS):
        left, right = rng.sample(ids, 2)
        if len(links[left]) < targets[left] and len(links[right]) < targets[right]:
            links[left].add(right)
            links[right].add(left)
    stamp = database.to_db_text(config.local_now(now))
    for user_id in sorted(links):
        for friend_id in sorted(links[user_id]):
            if user_id < friend_id:
                friends.connect_demo_friends(connection, user_id, friend_id, stamp)


def _candidate_events(connection, start, end):
    """Read visible, placeable occurrences in stable chronological and ID order."""
    frame = database.get_events_df(connection, start, end)
    events = []
    for row in frame.reset_index().to_dict('records'):
        event = models.event_from_row(row)
        if event.status not in config.HIDDEN_STATUSES and gaps.placement_problem(event) is None:
            events.append(event)
    return sorted(events, key=lambda event: (event.start, event.event_id))


def _weighted_events(candidates, person, count, rng):
    """Draw unique events using focus-driven affinity and favorites, with bounded retries."""
    weights = []
    for event in candidates:
        affinity = max(0, person['tastes'][event.bundle_key])
        favorite = bool(person['profile'].favorite_kinds(event))
        weights.append(1 + config.SYNTHETIC_DRAW_AFFINITY * affinity
                       + config.SYNTHETIC_DRAW_FAVORITE * favorite)
    chosen, ids = [], set()
    for attempt in range(config.SYNTHETIC_MAX_ATTEMPTS):
        if len(chosen) >= min(count, len(candidates)):
            break
        event = rng.choices(candidates, weights=weights)[0]
        if event.event_id not in ids:
            chosen.append(event)
            ids.add(event.event_id)
    return chosen


def _rating_pattern(event):
    """Express the three nonlinear time/preferences effects specified in section 17.3."""
    if event.direction_key == 'career':
        if event.start.weekday() >= config.ML_WEEKEND_START:
            return -config.SYNTHETIC_RATING_PATTERN
        first, last = config.SYNTHETIC_CAREER_HOURS
        if first <= event.start.hour < last:
            return config.SYNTHETIC_RATING_PATTERN
    if event.direction_key == 'sports' and event.start.hour >= config.SYNTHETIC_SPORT_LATE_HOUR:
        return -config.SYNTHETIC_RATING_PATTERN
    return 0


def _synthetic_rating(event, person, friend_count, rng):
    """Apply the specified noisy preference formula and clamp rounded stars to one through five."""
    profile = person['profile']
    mean = (config.SYNTHETIC_RATING_BASE
            + config.SYNTHETIC_RATING_AFFINITY * person['tastes'][event.bundle_key]
            + config.SYNTHETIC_RATING_FOCUS * profile.wants_direction(event)
            + config.SYNTHETIC_RATING_FAVORITE * bool(profile.favorite_kinds(event))
            + config.SYNTHETIC_RATING_FRIEND
            * min(friend_count, config.SYNTHETIC_RATING_FRIEND_CAP) + _rating_pattern(event))
    rating = round(mean + rng.gauss(0, config.SYNTHETIC_RATING_NOISE))
    return min(config.RATING_MAX, max(config.RATING_MIN, rating))


def _synthetic_confirmations(connection, people, past, future, rng):
    """Save all confirmations before rating so social counts do not depend on user iteration."""
    pending = []
    for person in people:
        user_id = person['profile'].user_id
        selected = _weighted_events(past, person, rng.randint(*config.SYNTHETIC_PAST_COUNT), rng)
        selected += _weighted_events(future, person,
                                      rng.randint(*config.SYNTHETIC_FUTURE_COUNT), rng)
        for event in selected:
            confirmed = event.start - timedelta(days=rng.randint(*config.SYNTHETIC_CONFIRM_DAYS))
            database.save_interaction(connection, user_id, event.event_id, 'confirm', now=confirmed)
            if rng.random() < config.SYNTHETIC_CANCEL_SHARE:
                database.save_interaction(connection, user_id, event.event_id, 'cancel',
                                          now=confirmed + timedelta(hours=1))
            else:
                pending.append((person, event))
    return pending


def create_synthetic_interactions(connection, rng, now=None, people=None):
    """Create weighted confirmations, attendance and ratings using only a supplied private RNG."""
    now = config.local_now(now)
    if people is None:
        bundles = database.get_categories_df(connection).reset_index().to_dict('records')
        people = []
        for user_id in database.get_synthetic_users_df(connection).index:
            profile = database.get_user_profile(connection, int(user_id))
            people.append({'profile': profile, 'tastes': _affinities(profile, bundles, rng)})
    candidates = _candidate_events(connection, now - timedelta(weeks=config.HISTORY_WEEKS),
                                   now + timedelta(days=config.SYNTHETIC_FUTURE_DAYS))
    past = [event for event in candidates if event.end < now]
    future = [event for event in candidates if event.start > now]
    pending = _synthetic_confirmations(connection, people, past, future, rng)
    for person, event in pending:
        if event.end >= now:
            continue
        user_id = person['profile'].user_id
        delay = timedelta(hours=rng.randint(*config.SYNTHETIC_ANSWER_HOURS))
        answered = min(now, event.end + delay)
        action = 'attended' if rng.random() < config.SYNTHETIC_ATTEND_SHARE else 'not_attended'
        database.save_interaction(connection, user_id, event.event_id, action, now=answered)
        if action == 'attended':
            counts = friends.friends_going_counts(connection, user_id, [event.event_id])
            rating = _synthetic_rating(event, person, counts.get(event.event_id, 0), rng)
            database.save_interaction(connection, user_id, event.event_id, 'rate', rating, answered)


def check_synthetic_data(connection, now=None):
    """Reject insufficient, single-direction or imbalanced generated training examples."""
    frame = database.get_training_interactions_df(connection, now)
    frame = frame.loc[frame['is_synthetic'] == 1]
    if len(frame) < config.SYNTHETIC_MIN_RATINGS:
        raise ValueError('Synthetic data needs at least 500 attended, rated interactions.')
    share = float((frame['rating'] >= config.LABEL_MIN_STARS).mean())
    low, high = config.SYNTHETIC_POSITIVE_SHARE
    if not low <= share <= high:
        raise ValueError(f'Synthetic positive-rating share {share:.1%} is outside 35–65%.')
    if set(frame['direction_key']) != set(config.DIRECTION_LABELS):
        raise ValueError('Synthetic ratings must cover Sports, Leisure and Career.')
    return {'rated_interactions': len(frame), 'positive_share': share}


def ensure_synthetic_data(connection, now=None, rng=None):
    """Upgrade an M3 database once, retrying interrupted seeds without resetting local data."""
    if database.get_setting(connection, 'synthetic_setup_done') == '1':
        return
    now = config.local_now(now)
    rng = rng or random.Random(config.RANDOM_SEED)
    database.remove_incomplete_synthetic_seed(connection)
    people = create_synthetic_users(connection, rng, now)
    create_synthetic_friendships(connection, rng, now)
    create_synthetic_interactions(connection, rng, now, people)
    check_synthetic_data(connection, now)
    database.set_setting(connection, 'synthetic_setup_done', '1')


def _demo_fitting_events(connection, start, end, demo_path):
    """Filter against the demo calendar alone, without ever reading the user's private calendar."""
    if not demo_path.exists():
        ensure_demo_calendar(connection, demo_path, start)
    text = demo_path.read_text(encoding='utf-8')
    blocks, labels, known = calendar_import.parse_calendar(text, start, end)
    intervals = [(block.start, block.end) for block in blocks]
    by_day, fitting = {}, []
    for event in _candidate_events(connection, start, end):
        day = event.start.date()
        if day not in by_day:
            by_day[day] = gaps.find_gaps_for_day(day, intervals)
        if any(gap.fits(event) for gap in by_day[day]):
            fitting.append(event)
    return fitting


def create_demo_history(connection, user_id, now=None, demo_path=config.DEMO_CALENDAR_FILE):
    """Seed up to six fitting local demo rows, reserving two recent events for pending feedback."""
    now = config.local_now(now)
    profile = database.get_user_profile(connection, user_id)
    start = now - timedelta(days=config.DEMO_HISTORY_DAYS)
    events = _demo_fitting_events(connection, start, now, demo_path)
    interactions = database.get_user_interactions_df(connection, user_id)
    existing = set(interactions.loc[interactions['is_demo'] == 0, 'event_id'])
    suitable = []
    for event in events:
        if event.end < now and profile.wants_direction(event) and event.event_id not in existing:
            suitable.append(event)
    cutoff = now - timedelta(days=config.DEMO_PENDING_DAYS)
    recent = [event for event in suitable if event.end >= cutoff]
    pending = recent[-config.DEMO_PENDING_COUNT:]
    answered = [event for event in suitable if event not in pending]
    states = list(zip(answered, [*config.DEMO_HISTORY_RATINGS, None]))
    created = []
    for event, rating in states + [(event, None) for event in pending]:
        if database.get_interaction(connection, user_id, event.event_id) is not None:
            created.append(event.event_id)
            continue
        database.save_interaction(connection, user_id, event.event_id, 'confirm',
                                  now=event.start - timedelta(days=1), is_demo=True)
        if event not in pending:
            answer_time = min(now, event.end + timedelta(hours=1))
            action = 'attended' if rating is not None else 'not_attended'
            database.save_interaction(connection, user_id, event.event_id, action, now=answer_time)
            if rating is not None:
                database.save_interaction(connection, user_id, event.event_id, 'rate',
                                          rating, answer_time)
        created.append(event.event_id)
    return created


def create_showcase_friends(connection, user_id, now=None, demo_path=config.DEMO_CALENDAR_FILE):
    """Connect three showcase profiles and seed fitting future plans and two demo invitations."""
    now = config.local_now(now)
    end = datetime.combine(gaps.week_start(now), datetime.min.time())
    end += timedelta(days=config.SYNTHETIC_FUTURE_DAYS)
    fitting = _demo_fitting_events(connection, now, end, demo_path)
    events = [event for event in fitting if event.start > now]
    people = database.get_synthetic_users_df(connection)
    for index, code in enumerate(config.SHOWCASE_CODES[:config.SHOWCASE_PRE_ADDED]):
        matching = people.loc[people['friend_code'] == code]
        if matching.empty:
            continue
        friend_id = int(matching.index[0])
        friends.connect_demo_friends(connection, user_id, friend_id, database.to_db_text(now))
        for event_index, event in enumerate(events[:config.SHOWCASE_PRE_ADDED]):
            previous = database.get_interaction(connection, friend_id, event.event_id)
            if previous is None or previous['status'] == 'cancelled':
                database.save_interaction(connection, friend_id, event.event_id, 'confirm', now=now)
            if index < config.SHOWCASE_INVITATIONS and event_index == index:
                friends.create_demo_invitation(connection, friend_id, user_id, event.event_id,
                                                database.to_db_text(now))


